import crypto from 'crypto';
import jwt from 'jsonwebtoken';
const LIVE_TOKEN_TTL_SECONDS = 10 * 60;
function optionalEnv(name) {
    const value = process.env[name]?.trim();
    return value ? value : null;
}
function privateKey() {
    const encoded = optionalEnv('SUPABASE_REALTIME_PRIVATE_KEY_BASE64');
    if (encoded) {
        try {
            const decoded = Buffer.from(encoded, 'base64').toString('utf8');
            // `supabase gen signing-key --algorithm ES256` returns a private JWK.
            // PEM remains supported for deployments that keep the key in that format.
            return decoded.trim().startsWith('{')
                ? crypto.createPrivateKey({ key: JSON.parse(decoded), format: 'jwk' })
                : decoded;
        }
        catch {
            return null;
        }
    }
    return optionalEnv('SUPABASE_REALTIME_PRIVATE_KEY')?.replace(/\\n/g, '\n') || null;
}
function config() {
    if (process.env.LIVE_MONITORING_ENABLED !== 'true')
        return null;
    const supabaseUrl = optionalEnv('SUPABASE_URL');
    const supabasePublishableKey = optionalEnv('SUPABASE_PUBLISHABLE_KEY');
    const key = privateKey();
    if (!supabaseUrl || !supabasePublishableKey || !key)
        return null;
    try {
        const parsed = new URL(supabaseUrl);
        if (parsed.protocol !== 'https:')
            return null;
    }
    catch {
        return null;
    }
    return { supabaseUrl, supabasePublishableKey, key, keyId: optionalEnv('SUPABASE_REALTIME_JWT_KEY_ID') };
}
export function liveMonitoringEnabled() {
    return config() !== null;
}
export function liveTopic(batchId, studentId, jti) {
    // jti is UUID generated by the server; hash avoids putting an auth-session identifier in topic names.
    const attempt = crypto.createHash('sha256').update(jti).digest('hex').slice(0, 24);
    return `live:batch:${batchId}:student:${studentId}:attempt:${attempt}`;
}
function staticStun() {
    return [{ urls: ['stun:stun.relay.metered.ca:80', 'stun:stun.relay.metered.ca:443'] }];
}
function isSafeIceServer(value) {
    if (!value || typeof value !== 'object')
        return false;
    const server = value;
    const urls = Array.isArray(server.urls) ? server.urls : [server.urls];
    return urls.length > 0 && urls.length <= 8 && urls.every((url) => typeof url === 'string'
        && /^(stun:|turn:|turns:)/.test(url) && url.length <= 300)
        && (!server.username || server.username.length <= 512)
        && (!server.credential || server.credential.length <= 1024);
}
async function openRelayIceServers() {
    const endpoint = optionalEnv('OPEN_RELAY_CREDENTIALS_URL');
    const apiKey = optionalEnv('OPEN_RELAY_API_KEY');
    if (!endpoint || !apiKey)
        return { iceServers: staticStun(), turnAvailable: false };
    try {
        const url = new URL(endpoint);
        if (url.protocol !== 'https:' || !url.hostname.endsWith('.metered.live'))
            throw new Error('invalid relay endpoint');
        url.searchParams.set('apiKey', apiKey);
        const response = await fetch(url, { signal: AbortSignal.timeout(5_000) });
        if (!response.ok)
            throw new Error(`relay status ${response.status}`);
        const raw = await response.json();
        if (!Array.isArray(raw))
            throw new Error('relay returned non-array');
        const turn = raw.filter(isSafeIceServer);
        return { iceServers: [...staticStun(), ...turn], turnAvailable: turn.some((item) => {
                const urls = Array.isArray(item.urls) ? item.urls : [item.urls];
                return urls.some((url) => url.startsWith('turn:') || url.startsWith('turns:'));
            }) };
    }
    catch (error) {
        console.warn('[live-monitor] TURN credentials unavailable; continuing P2P-only', error instanceof Error ? error.message : error);
        return { iceServers: staticStun(), turnAvailable: false };
    }
}
export async function issueLiveSession(input) {
    const current = config();
    if (!current)
        return { enabled: false };
    const topic = liveTopic(input.batchId, input.studentId, input.jti);
    const now = Math.floor(Date.now() / 1000);
    const realtimeToken = jwt.sign({
        iss: `${current.supabaseUrl}/auth/v1`,
        aud: 'authenticated',
        role: 'authenticated',
        sub: input.subject,
        live_topic: topic,
        live_actor: input.actor,
        iat: now,
    }, current.key, {
        algorithm: 'ES256',
        expiresIn: LIVE_TOKEN_TTL_SECONDS,
        ...(current.keyId ? { keyid: current.keyId } : {}),
    });
    const relay = await openRelayIceServers();
    return {
        enabled: true,
        topic,
        realtimeToken,
        supabaseUrl: current.supabaseUrl,
        supabasePublishableKey: current.supabasePublishableKey,
        iceServers: relay.iceServers,
        turnAvailable: relay.turnAvailable,
        expiresAt: new Date((now + LIVE_TOKEN_TTL_SECONDS) * 1000).toISOString(),
    };
}
export function attemptHash(jti) {
    return crypto.createHash('sha256').update(jti).digest('hex');
}
